import{_ as r,o as t,c as a,a3 as o}from"./chunks/framework.DBpCFmh2.js";const b=JSON.parse('{"title":"流式响应处理器","description":"本文件面向“流式响应处理器”，聚焦本项目中基于 SSE（Server-Sent Events）的流式输出链路。","frontmatter":{"title":"流式响应处理器","description":"本文件面向“流式响应处理器”，聚焦本项目中基于 SSE（Server-Sent Events）的流式输出链路。"},"headers":[],"relativePath":"Chrome-扩展核心/Side-Panel-界面架构/聊天管理系统/流式响应处理器/index.md","filePath":"Chrome-扩展核心/Side-Panel-界面架构/聊天管理系统/流式响应处理器/index.md","lastUpdated":null}'),l={name:"Chrome-扩展核心/Side-Panel-界面架构/聊天管理系统/流式响应处理器/index.md"};function i(n,e,c,s,d,h){return t(),a("div",null,[...e[0]||(e[0]=[o(`<h1 id="流式响应处理器" tabindex="-1">流式响应处理器 <a class="header-anchor" href="#流式响应处理器" aria-label="Permalink to &quot;流式响应处理器&quot;">​</a></h1><details class="details custom-block"><summary>本文引用的源码文件</summary><p><strong>本文引用的文件</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/stream-controller.js" target="_blank" rel="noreferrer">src/background/stream-controller.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/react-loop.js" target="_blank" rel="noreferrer">src/background/react-loop.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/chat-streaming.js" target="_blank" rel="noreferrer">src/side_panel/chat-streaming.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/index.js" target="_blank" rel="noreferrer">src/background/index.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/config/constants.js" target="_blank" rel="noreferrer">src/config/constants.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/test/unit/sw-heartbeat.unit.test.js" target="_blank" rel="noreferrer">test/unit/sw-heartbeat.unit.test.js</a></li></ul></details><h2 id="目录" tabindex="-1">目录 <a class="header-anchor" href="#目录" aria-label="Permalink to &quot;目录&quot;">​</a></h2><ol><li><a href="#引言">引言</a></li><li><a href="#项目结构中的流式处理位置">项目结构中的流式处理位置</a></li><li><a href="#核心组件总览">核心组件总览</a></li><li><a href="#架构总览从模型响应到侧面板渲染">架构总览：从模型响应到侧面板渲染</a></li><li><a href="#sse-连接与生命周期管理">SSE 连接与生命周期管理</a></li><li><a href="#增量更新算法">增量更新算法</a></li><li><a href="#流式数据解析与完整性校验">流式数据解析与完整性校验</a></li><li><a href="#错误恢复机制">错误恢复机制</a></li><li><a href="#暂停恢复与状态同步">暂停、恢复与状态同步</a></li><li><a href="#性能优化">性能优化</a></li><li><a href="#调试与监控">调试与监控</a></li><li><a href="#使用示例与最佳实践">使用示例与最佳实践</a></li><li><a href="#故障排查清单">故障排查清单</a></li><li><a href="#结论">结论</a></li></ol><h2 id="引言" tabindex="-1">引言 <a class="header-anchor" href="#引言" aria-label="Permalink to &quot;引言&quot;">​</a></h2><p>本文件面向“流式响应处理器”，聚焦本项目中基于 SSE（Server-Sent Events）的流式输出链路。该链路的核心目标是：在扩展端后台进程读取模型 API 的流式响应后，将文本增量、工具调用、推理内容、Token 用量等数据实时推送到侧面板，并在 UI 上实现思考过程、工具卡片、执行结果和最终消息的渐进式呈现。</p><p>需要特别区分两个概念：</p><ul><li><strong>模型 API 的 SSE 流</strong>：由 <code>StreamController</code> 与 <code>readSSEStream</code> 负责解析 OpenAI 兼容格式的 <code>data:</code> 行，提取 <code>choices.delta.content</code>、<code>tool_calls</code>、<code>finish_reason</code> 与 <code>usage</code>。</li><li><strong>扩展内部的消息通道</strong>：通过 <code>chrome.runtime.sendMessage</code> 向侧面板发送 <code>STREAM_START</code>、<code>STREAM_CHUNK</code>、<code>STREAM_TOOL_CALL</code>、<code>STREAM_DONE</code> 等事件；这不是浏览器原生 <code>EventSource</code>，而是扩展进程间消息协议。</li></ul><p>此外，项目中还存在 Agent 端心跳与健康检查逻辑，但它是针对本地代理进程的保活机制，并非模型 SSE 连接的心跳。文档会在相应章节明确区分这两者。</p><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/stream-controller.js#L1-L10" target="_blank" rel="noreferrer">src/background/stream-controller.js#L1-L10</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/stream-controller.js#L287-L409" target="_blank" rel="noreferrer">src/background/stream-controller.js#L287-L409</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/index.js#L2250-L2306" target="_blank" rel="noreferrer">src/background/index.js#L2250-L2306</a></li></ul><h2 id="项目结构中的流式处理位置" tabindex="-1">项目结构中的流式处理位置 <a class="header-anchor" href="#项目结构中的流式处理位置" aria-label="Permalink to &quot;项目结构中的流式处理位置&quot;">​</a></h2><p>流式响应处理主要分布在三个层次：</p><table tabindex="0"><thead><tr><th>层次</th><th>文件</th><th>职责</th></tr></thead><tbody><tr><td>后台流式控制器</td><td><code>src/background/stream-controller.js</code></td><td>解析 SSE 行、合并增量、节流发送、检测工具调用、提取 usage、构造最终结果</td></tr><tr><td>ReAct 循环入口</td><td><code>src/background/react-loop.js</code></td><td>发起 fetch、选择流式或非流式分支、包装 StreamController、记录执行日志、处理上下文超限自愈</td></tr><tr><td>侧面板渲染层</td><td><code>src/side_panel/chat-streaming.js</code></td><td>创建流式消息容器、增量 Markdown 渲染、工具卡片展示、滚动控制、状态同步</td></tr></tbody></table><pre class="mermaid">graph TB
Background[&quot;后台进程&lt;br/&gt;react-loop.js&quot;] --&gt; StreamController[&quot;流式控制器&lt;br/&gt;stream-controller.js&quot;]
StreamController --&gt; APIServer[&quot;模型 API&lt;br/&gt;OpenAI 兼容 SSE&quot;]
StreamController --&gt; SidePanel[&quot;侧面板&lt;br/&gt;chat-streaming.js&quot;]
Background --&gt; SidePanel
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/react-loop.js#L1460-L1488" target="_blank" rel="noreferrer">src/background/react-loop.js#L1460-L1488</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/stream-controller.js#L36-L281" target="_blank" rel="noreferrer">src/background/stream-controller.js#L36-L281</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/chat-streaming.js#L677-L726" target="_blank" rel="noreferrer">src/side_panel/chat-streaming.js#L677-L726</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/stream-controller.js#L1-L53" target="_blank" rel="noreferrer">src/background/stream-controller.js#L1-L53</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/react-loop.js#L1460-L1488" target="_blank" rel="noreferrer">src/background/react-loop.js#L1460-L1488</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/chat-streaming.js#L1-L19" target="_blank" rel="noreferrer">src/side_panel/chat-streaming.js#L1-L19</a></li></ul><h2 id="核心组件总览" tabindex="-1">核心组件总览 <a class="header-anchor" href="#核心组件总览" aria-label="Permalink to &quot;核心组件总览&quot;">​</a></h2><h3 id="streamcontroller-sse-解析与增量聚合" tabindex="-1">StreamController：SSE 解析与增量聚合 <a class="header-anchor" href="#streamcontroller-sse-解析与增量聚合" aria-label="Permalink to &quot;StreamController：SSE 解析与增量聚合&quot;">​</a></h3><p><code>StreamController</code> 是流式响应的核心对象。它维护以下关键状态：</p><table tabindex="0"><thead><tr><th>字段或方法</th><th>作用</th><th>复杂度说明</th></tr></thead><tbody><tr><td><code>fullContent</code></td><td>累积完整文本内容</td><td>字符串拼接，时间复杂度与增量长度线性相关</td></tr><tr><td><code>reasoningContent</code></td><td>累积推理内容（如 DeepSeek thinking mode）</td><td>同上</td></tr><tr><td><code>usage</code></td><td>最终 Token 用量</td><td>通常只被最后一次独立 chunk 覆盖</td></tr><tr><td><code>toolCalls</code></td><td>按 index 累积工具调用片段</td><td>可能形成稀疏数组，需规范化</td></tr><tr><td><code>isStreaming</code></td><td>标记当前是否处于流式阶段</td><td>用于避免重复发送 start/done</td></tr><tr><td><code>_pendingChunk</code></td><td>节流缓冲区</td><td>减少频繁 DOM 更新</td></tr><tr><td><code>feedLine(line)</code></td><td>解析单行 SSE 数据</td><td>每次调用 O(1)，JSON 解析成本取决于 chunk 大小</td></tr><tr><td><code>sendChunk(content)</code></td><td>节流合并并发送 <code>STREAM_CHUNK</code></td><td>根据 <code>streamChunkDelay</code> 控制频率</td></tr><tr><td><code>finish()</code></td><td>发送 <code>STREAM_DONE</code> 并返回最终结果</td><td>包含 tool_calls 规范化</td></tr><tr><td><code>sendToolCallNotification()</code></td><td>发送 <code>STREAM_TOOL_CALL</code></td><td>在检测到 <code>finish_reason === &#39;tool_calls&#39;</code> 时触发</td></tr></tbody></table><pre class="mermaid">classDiagram
class StreamController {
+string sessionId
+string callId
+object config
+string fullContent
+string reasoningContent
+object usage
+array toolCalls
+boolean isStreaming
+number lastSendTime
-string _pendingChunk
-boolean _streamStarted
-boolean _streamDone
-function _sendFn
-string _typePrefix
+constructor(sessionId, streamConfig, options)
+feedLine(line) object
+sendStart() void
+sendChunk(content) void
-_flushChunk() void
+finish() void
+sendToolCallNotification() void
+reset() void
+getResult() object
}
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/stream-controller.js#L36-L281" target="_blank" rel="noreferrer">src/background/stream-controller.js#L36-L281</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/stream-controller.js#L36-L168" target="_blank" rel="noreferrer">src/background/stream-controller.js#L36-L168</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/stream-controller.js#L170-L281" target="_blank" rel="noreferrer">src/background/stream-controller.js#L170-L281</a></li></ul><h3 id="readssestream-readablestream-读取与空闲超时保护" tabindex="-1">readSSEStream：ReadableStream 读取与空闲超时保护 <a class="header-anchor" href="#readssestream-readablestream-读取与空闲超时保护" aria-label="Permalink to &quot;readSSEStream：ReadableStream 读取与空闲超时保护&quot;">​</a></h3><p><code>readSSEStream</code> 负责从 <code>fetchResponse.body.getReader()</code> 中逐块读取二进制数据，解码为文本，按行拆分，再交给 <code>StreamController.feedLine</code>。其关键特性包括：</p><ul><li>立即调用 <code>controller.sendStart()</code>，让前端尽早显示“思考中”。</li><li>使用 <code>TextDecoder</code> 进行流式解码。</li><li>使用 <code>Promise.race</code> 同时监听 <code>reader.read()</code>、空闲超时和 <code>abortSignal</code>。</li><li>空闲超时默认 120 秒，名称为 <code>StreamIdleTimeout</code>。</li><li>遇到 <code>AbortError</code> 不发送 <code>STREAM_DONE</code>，避免残留消息污染后续任务。</li><li>遇到空闲超时主动 <code>reader.cancel()</code>，然后调用 <code>controller.finish()</code> 并抛出异常。</li><li>正常结束时调用 <code>controller.finish()</code>，返回 <code>{ status: &#39;done&#39;, ...result }</code>。</li><li>当检测到 <code>finish_reason === &#39;tool_calls&#39;</code> 时提前返回 <code>{ status: &#39;tool_calls&#39;, ...result }</code>，供 ReAct 循环继续执行工具。</li></ul><pre class="mermaid">flowchart TD
Start([&quot;进入 readSSEStream&quot;]) --&gt; SendStart[&quot;发送 STREAM_START&quot;]
SendStart --&gt; Loop{&quot;还有数据？&quot;}
Loop --&gt; |否| Finish[&quot;调用 controller.finish()&quot;]
Finish --&gt; Done[&quot;返回 done 结果&quot;]
Loop --&gt; |是| Read[&quot;reader.read()&quot;]
Read --&gt; Race[&quot;Promise.race&lt;br/&gt;空闲超时 / Abort / 数据&quot;]
Race --&gt; Decode[&quot;解码并拼接 buffer&quot;]
Decode --&gt; Split[&quot;按换行符拆分&quot;]
Split --&gt; Feed[&quot;controller.feedLine(line)&quot;]
Feed --&gt; TypeCheck{&quot;事件类型？&quot;}
TypeCheck --&gt; |content| SendChunk[&quot;节流发送 STREAM_CHUNK&quot;]
TypeCheck --&gt; |tool_calls| ToolCall[&quot;发送 STREAM_TOOL_CALL 并返回 tool_calls 结果&quot;]
TypeCheck --&gt; |done| MarkDone[&quot;标记 _streamDone&quot;]
TypeCheck --&gt; |ignore| Next[&quot;继续下一行&quot;]
SendChunk --&gt; Loop
MarkDone --&gt; Loop
ToolCall --&gt; End([&quot;结束&quot;])
Next --&gt; Loop
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/stream-controller.js#L287-L409" target="_blank" rel="noreferrer">src/background/stream-controller.js#L287-L409</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/stream-controller.js#L287-L409" target="_blank" rel="noreferrer">src/background/stream-controller.js#L287-L409</a></li></ul><h3 id="chat-streaming-js-侧面板流式渲染" tabindex="-1">chat-streaming.js：侧面板流式渲染 <a class="header-anchor" href="#chat-streaming-js-侧面板流式渲染" aria-label="Permalink to &quot;chat-streaming.js：侧面板流式渲染&quot;">​</a></h3><p>侧面板负责把后台推送的事件转化为可交互的 UI。核心职责包括：</p><ul><li>创建流式消息容器，包含思考指示器、停止按钮、状态区域。</li><li>增量渲染 Markdown 内容，支持多轮 ReAct 迭代。</li><li>隐藏思考指示器并插入“思考结果”徽章。</li><li>渲染工具调用卡片，支持展开/折叠、复制参数、终止命令、终止等待。</li><li>智能滚动到底部，尊重用户手动上滚。</li><li>重连流式元素，补充脱落期间缺失的内容。</li><li>管理流式状态访问器，防止多会话并行串台。</li></ul><pre class="mermaid">sequenceDiagram
participant BG as &quot;后台 react-loop.js&quot;
participant SC as &quot;StreamController&quot;
participant SP as &quot;侧面板 chat-streaming.js&quot;
BG-&gt;&gt;SC : 创建 StreamController
SC--&gt;&gt;SP : STREAM_START
SP-&gt;&gt;SP : 创建流式消息容器
loop 每个 SSE chunk
SC--&gt;&gt;SP : STREAM_CHUNK
SP-&gt;&gt;SP : updateStreamingMessage(fullContent)
end
SC--&gt;&gt;SP : STREAM_TOOL_CALL
SP-&gt;&gt;SP : appendToolCallItems(toolCalls)
SC--&gt;&gt;SP : STREAM_DONE
SP-&gt;&gt;SP : finalizeStreamingMessage
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/stream-controller.js#L171-L252" target="_blank" rel="noreferrer">src/background/stream-controller.js#L171-L252</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/chat-streaming.js#L677-L726" target="_blank" rel="noreferrer">src/side_panel/chat-streaming.js#L677-L726</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/chat-streaming.js#L887-L1116" target="_blank" rel="noreferrer">src/side_panel/chat-streaming.js#L887-L1116</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/chat-streaming.js#L677-L874" target="_blank" rel="noreferrer">src/side_panel/chat-streaming.js#L677-L874</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/chat-streaming.js#L887-L1116" target="_blank" rel="noreferrer">src/side_panel/chat-streaming.js#L887-L1116</a></li></ul><h2 id="架构总览-从模型响应到侧面板渲染" tabindex="-1">架构总览：从模型响应到侧面板渲染 <a class="header-anchor" href="#架构总览-从模型响应到侧面板渲染" aria-label="Permalink to &quot;架构总览：从模型响应到侧面板渲染&quot;">​</a></h2><p>下图展示了 ReAct 循环中一次 API 调用的完整流程，包括流式与非流式分支、工具调用检测和最终结果组装。</p><pre class="mermaid">sequenceDiagram
participant RL as &quot;react-loop.js&quot;
participant HTTP as &quot;HTTP 请求&quot;
participant SC as &quot;StreamController&quot;
participant SP as &quot;chat-streaming.js&quot;
RL-&gt;&gt;HTTP : 发起模型 API 请求
alt 流式模式且存在 body
RL-&gt;&gt;SC : new StreamController(sessionId, streamConfig, options)
RL-&gt;&gt;SC : readSSEStream(reader, controller, abortSignal)
SC-&gt;&gt;SP : STREAM_START
loop SSE data 行
SC-&gt;&gt;SC : feedLine(data)
alt content
SC-&gt;&gt;SP : STREAM_CHUNK(delta)
else tool_calls
SC-&gt;&gt;SP : STREAM_TOOL_CALL(toolCalls)
SC--&gt;&gt;RL : 返回 tool_calls 结果
else done
SC-&gt;&gt;SP : STREAM_DONE(finalContent, usage, toolCalls)
SC--&gt;&gt;RL : 返回 done 结果
end
end
else 非流式模式
HTTP--&gt;&gt;RL : 完整 JSON 响应
RL-&gt;&gt;RL : 解析 JSON 并规范化 tool_calls
end
RL-&gt;&gt;RL : 记录执行日志、Token 统计、状态更新
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/react-loop.js#L1460-L1488" target="_blank" rel="noreferrer">src/background/react-loop.js#L1460-L1488</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/stream-controller.js#L287-L409" target="_blank" rel="noreferrer">src/background/stream-controller.js#L287-L409</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/chat-streaming.js#L677-L726" target="_blank" rel="noreferrer">src/side_panel/chat-streaming.js#L677-L726</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/react-loop.js#L1460-L1649" target="_blank" rel="noreferrer">src/background/react-loop.js#L1460-L1649</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/stream-controller.js#L287-L409" target="_blank" rel="noreferrer">src/background/stream-controller.js#L287-L409</a></li></ul><h2 id="sse-连接与生命周期管理" tabindex="-1">SSE 连接与生命周期管理 <a class="header-anchor" href="#sse-连接与生命周期管理" aria-label="Permalink to &quot;SSE 连接与生命周期管理&quot;">​</a></h2><h3 id="连接建立" tabindex="-1">连接建立 <a class="header-anchor" href="#连接建立" aria-label="Permalink to &quot;连接建立&quot;">​</a></h3><p>本项目没有使用浏览器原生 <code>EventSource</code> 来连接模型 API，而是使用 <code>fetch</code> 获取 <code>Response.body</code>，再通过 <code>getReader()</code> 获得 <code>ReadableStream</code>。<code>readSSEStream</code> 直接消费该流，因此：</p><ul><li>连接建立由 <code>fetch</code> 完成。</li><li>流读取由 <code>readSSEStream</code> 管理。</li><li>后端解析由 <code>StreamController</code> 完成。</li><li>前端渲染由 <code>chat-streaming.js</code> 消费 <code>STREAM_*</code> 消息完成。</li></ul><p>这种设计允许更细粒度的控制，例如自定义空闲超时、主动取消 reader、在工具调用中途退出流式读取。</p><h3 id="心跳检测" tabindex="-1">心跳检测 <a class="header-anchor" href="#心跳检测" aria-label="Permalink to &quot;心跳检测&quot;">​</a></h3><p>需要严格区分两类心跳：</p><table tabindex="0"><thead><tr><th>类型</th><th>目标</th><th>实现位置</th><th>是否 SSE 心跳</th></tr></thead><tbody><tr><td>模型 SSE 空闲超时</td><td>检测流式数据卡住</td><td><code>stream-controller.js</code> 中 <code>STREAM_IDLE_TIMEOUT_MS</code></td><td>不是传统 SSE 心跳，而是“无数据超时”保护</td></tr><tr><td>Agent 健康检查与心跳</td><td>检测本地代理进程</td><td><code>src/background/index.js</code> 中 <code>startAgentHealthCheck</code>、<code>performAgentHeartbeat</code></td><td>不是模型 SSE 心跳，是扩展与 Agent 之间的保活</td></tr></tbody></table><p>模型 SSE 空闲超时默认 120 秒，每次收到数据块都会重置计时器。如果持续无 SSE 事件，则抛出 <code>StreamIdleTimeout</code>。</p><p>Agent 心跳每 60 秒向活跃代理发送一次轻量 GET 请求，用于刷新代理端的认证时间，使其感知插件在线。</p><pre class="mermaid">stateDiagram-v2
[*] --&gt; 未连接
未连接 --&gt; 已连接 : &quot;fetch 成功&quot;
已连接 --&gt; 接收数据 : &quot;reader.read() 返回数据&quot;
接收数据 --&gt; 已连接 : &quot;重置空闲计时器&quot;
接收数据 --&gt; 空闲超时 : &quot;超过 STREAM_IDLE_TIMEOUT_MS&quot;
空闲超时 --&gt; 已关闭 : &quot;reader.cancel()&quot;
已连接 --&gt; 已关闭 : &quot;用户取消 / AbortError&quot;
已连接 --&gt; 工具调用 : &quot;finish_reason = tool_calls&quot;
工具调用 --&gt; 已关闭 : &quot;ReAct 继续执行工具&quot;
接收数据 --&gt; 已完成 : &quot;[DONE] 或流结束&quot;
已完成 --&gt; 已关闭 : &quot;controller.finish()&quot;
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/stream-controller.js#L287-L409" target="_blank" rel="noreferrer">src/background/stream-controller.js#L287-L409</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/index.js#L2250-L2306" target="_blank" rel="noreferrer">src/background/index.js#L2250-L2306</a></li></ul><h3 id="自动重连" tabindex="-1">自动重连 <a class="header-anchor" href="#自动重连" aria-label="Permalink to &quot;自动重连&quot;">​</a></h3><p>在当前代码中，<strong>模型 SSE 流本身没有内置自动重连逻辑</strong>。<code>readSSEStream</code> 在空闲超时或网络错误时会抛出异常，由上层 <code>react-loop.js</code> 捕获并记录错误。</p><p>不过，项目实现了“上下文超限自愈”：当 HTTP 400 且错误信息包含 context、token、too long 等特征时，会强制裁剪消息并重试本轮。这属于业务层重试，而不是底层 SSE 重连。</p><p>对于 Agent 端，健康检查和心跳主要用于保持代理进程在线感知，并不直接对模型 SSE 做断线重连。</p><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/stream-controller.js#L287-L409" target="_blank" rel="noreferrer">src/background/stream-controller.js#L287-L409</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/react-loop.js#L1514-L1585" target="_blank" rel="noreferrer">src/background/react-loop.js#L1514-L1585</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/index.js#L2250-L2306" target="_blank" rel="noreferrer">src/background/index.js#L2250-L2306</a></li></ul><h3 id="优雅关闭" tabindex="-1">优雅关闭 <a class="header-anchor" href="#优雅关闭" aria-label="Permalink to &quot;优雅关闭&quot;">​</a></h3><p>优雅关闭的关键点如下：</p><ol><li>用户点击“停止生成”时，ReAct 循环会通过 <code>abortSignal</code> 中断 <code>reader.read()</code>。</li><li><code>readSSEStream</code> 捕获 <code>AbortError</code>，不调用 <code>controller.finish()</code>，避免发送残留 <code>STREAM_DONE</code>。</li><li>空闲超时时，先 <code>reader.cancel()</code> 释放底层流，再调用 <code>controller.finish()</code>，最后抛出异常。</li><li>正常结束时，调用 <code>controller.finish()</code>，发送 <code>STREAM_DONE</code>，包含最终内容、推理内容、usage 和规范化后的 tool_calls。</li><li>侧面板在流结束后清理流式状态，并将思考指示器替换为思考结果。</li></ol><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/stream-controller.js#L391-L409" target="_blank" rel="noreferrer">src/background/stream-controller.js#L391-L409</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/stream-controller.js#L220-L237" target="_blank" rel="noreferrer">src/background/stream-controller.js#L220-L237</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/chat-streaming.js#L728-L780" target="_blank" rel="noreferrer">src/side_panel/chat-streaming.js#L728-L780</a></li></ul><h2 id="增量更新算法" tabindex="-1">增量更新算法 <a class="header-anchor" href="#增量更新算法" aria-label="Permalink to &quot;增量更新算法&quot;">​</a></h2><h3 id="文本流式渲染" tabindex="-1">文本流式渲染 <a class="header-anchor" href="#文本流式渲染" aria-label="Permalink to &quot;文本流式渲染&quot;">​</a></h3><p><code>StreamController.feedLine</code> 会累积 <code>delta.content</code> 到 <code>fullContent</code>，然后通过 <code>sendChunk</code> 节流发送 <code>STREAM_CHUNK</code>。侧面板的 <code>updateStreamingMessage</code> 接收完整累积内容，并使用 Markdown 渲染函数重新渲染当前轮次的思考内容。</p><p>关键点：</p><ul><li>增量来自模型 SSE，但前端渲染的是累积全文，而非仅追加最后一个 delta。</li><li>思考过程中，思考指示器保持可见，首次出现内容时将“思考中”改为“输出中”。</li><li>多轮 ReAct 会追加多个 <code>thinking-content</code> 块，每轮结束后插入“思考结果”徽章。</li><li>滚动控制区分程序滚动和用户滚动，避免误判。</li></ul><pre class="mermaid">flowchart TD
Chunk[&quot;收到 STREAM_CHUNK&quot;] --&gt; Accumulate[&quot;累积 fullContent&quot;]
Accumulate --&gt; Render[&quot;updateStreamingMessage(fullContent)&quot;]
Render --&gt; Thinking{&quot;是否正在思考？&quot;}
Thinking --&gt; |是| UpdateThinking[&quot;更新 thinking-content&quot;]
Thinking --&gt; |否| UpdateFinal[&quot;更新最终思考内容&quot;]
UpdateThinking --&gt; Scroll[&quot;智能滚动到底部&quot;]
UpdateFinal --&gt; Scroll
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/stream-controller.js#L184-L217" target="_blank" rel="noreferrer">src/background/stream-controller.js#L184-L217</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/chat-streaming.js#L787-L874" target="_blank" rel="noreferrer">src/side_panel/chat-streaming.js#L787-L874</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/stream-controller.js#L184-L217" target="_blank" rel="noreferrer">src/background/stream-controller.js#L184-L217</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/chat-streaming.js#L787-L874" target="_blank" rel="noreferrer">src/side_panel/chat-streaming.js#L787-L874</a></li></ul><h3 id="工具调用实时显示" tabindex="-1">工具调用实时显示 <a class="header-anchor" href="#工具调用实时显示" aria-label="Permalink to &quot;工具调用实时显示&quot;">​</a></h3><p>当模型返回 <code>finish_reason === &#39;tool_calls&#39;</code> 时，<code>StreamController</code> 会：</p><ol><li>规范化 <code>toolCalls</code>。</li><li>先 flush 剩余内容，确保思考内容先显示。</li><li>发送 <code>STREAM_TOOL_CALL</code>，携带累积的 <code>toolCalls</code> 和 <code>fullContent</code>。</li><li>返回 <code>status: &#39;tool_calls&#39;</code>，让 ReAct 循环继续执行工具。</li></ol><p>侧面板收到 <code>STREAM_TOOL_CALL</code> 后，会隐藏思考指示器，插入“思考结果”徽章，并为每个工具调用创建卡片。卡片包含工具名、参数摘要、执行中状态、终止按钮和展开/折叠能力。</p><pre class="mermaid">sequenceDiagram
participant SC as &quot;StreamController&quot;
participant RL as &quot;react-loop.js&quot;
participant SP as &quot;chat-streaming.js&quot;
SC-&gt;&gt;SC : 检测到 finish_reason = tool_calls
SC-&gt;&gt;SC : normalizeToolCalls(toolCalls)
SC-&gt;&gt;SP : STREAM_TOOL_CALL(toolCalls, thinkingContent)
SP-&gt;&gt;SP : 隐藏思考指示器
SP-&gt;&gt;SP : 插入思考结果徽章
SP-&gt;&gt;SP : 渲染工具卡片
SC--&gt;&gt;RL : 返回 tool_calls 结果
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/stream-controller.js#L149-L165" target="_blank" rel="noreferrer">src/background/stream-controller.js#L149-L165</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/stream-controller.js#L347-L370" target="_blank" rel="noreferrer">src/background/stream-controller.js#L347-L370</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/chat-streaming.js#L887-L1116" target="_blank" rel="noreferrer">src/side_panel/chat-streaming.js#L887-L1116</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/stream-controller.js#L149-L165" target="_blank" rel="noreferrer">src/background/stream-controller.js#L149-L165</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/stream-controller.js#L347-L370" target="_blank" rel="noreferrer">src/background/stream-controller.js#L347-L370</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/chat-streaming.js#L887-L1116" target="_blank" rel="noreferrer">src/side_panel/chat-streaming.js#L887-L1116</a></li></ul><h3 id="进度条更新" tabindex="-1">进度条更新 <a class="header-anchor" href="#进度条更新" aria-label="Permalink to &quot;进度条更新&quot;">​</a></h3><p>当前代码中没有显式的“进度条”组件。流式进度主要通过以下方式体现：</p><ul><li>“思考中”“输出中”状态。</li><li>工具卡片上的“执行中…”状态。</li><li>工具完成后显示成功/失败状态和耗时。</li><li>极快完成的工具会设置最小显示延迟，确保用户能看到过渡状态。</li><li>滚动到底部按钮的 badge 提示有新内容待查看。</li></ul><p>如果需要真正的进度条，应基于 <code>STREAM_START</code>、<code>STREAM_TOOL_CALL</code>、<code>STREAM_DONE</code> 以及工具执行时长来计算，而不是依赖模型 SSE 的固定进度字段，因为模型流本身不提供统一进度值。</p><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/chat-streaming.js#L876-L885" target="_blank" rel="noreferrer">src/side_panel/chat-streaming.js#L876-L885</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/chat-streaming.js#L1136-L1200" target="_blank" rel="noreferrer">src/side_panel/chat-streaming.js#L1136-L1200</a></li></ul><h2 id="流式数据解析与完整性校验" tabindex="-1">流式数据解析与完整性校验 <a class="header-anchor" href="#流式数据解析与完整性校验" aria-label="Permalink to &quot;流式数据解析与完整性校验&quot;">​</a></h2><h3 id="json-流解析" tabindex="-1">JSON 流解析 <a class="header-anchor" href="#json-流解析" aria-label="Permalink to &quot;JSON 流解析&quot;">​</a></h3><p><code>StreamController.feedLine</code> 的处理顺序如下：</p><ol><li>忽略空行和注释行。</li><li>提取 <code>data:</code> 前缀后的内容。</li><li>识别 <code>[DONE]</code>。</li><li>尝试 <code>JSON.parse</code>，失败则忽略该行。</li><li>优先提取 <code>chunk.usage</code>，即使后续 <code>choices</code> 为空。</li><li>取 <code>choices[0]</code>，不存在则忽略。</li><li>累积 <code>reasoning_content</code>。</li><li>累积 <code>content</code>。</li><li>累积 <code>tool_calls</code>。</li><li>根据 <code>finish_reason</code> 决定返回类型。</li></ol><pre class="mermaid">flowchart TD
Line[&quot;SSE 行&quot;] --&gt; Prefix{&quot;是否 data: 行？&quot;}
Prefix --&gt; |否| Ignore[&quot;忽略&quot;]
Prefix --&gt; |是| DoneCheck{&quot;是否为 [DONE]？&quot;}
DoneCheck --&gt; |是| Done[&quot;返回 done&quot;]
DoneCheck --&gt; |否| Parse[&quot;JSON.parse&quot;]
Parse --&gt; Valid{&quot;解析成功？&quot;}
Valid --&gt; |否| Ignore
Valid --&gt; |是| Usage[&quot;提取 usage&quot;]
Usage --&gt; Choice{&quot;是否存在 choices[0]？&quot;}
Choice --&gt; |否| Ignore
Choice --&gt; |是| Delta[&quot;处理 delta&quot;]
Delta --&gt; Reasoning[&quot;累积 reasoning_content&quot;]
Delta --&gt; Content[&quot;累积 content&quot;]
Delta --&gt; Tools[&quot;累积 tool_calls&quot;]
Tools --&gt; Finish{&quot;finish_reason？&quot;}
Finish --&gt; Stop[&quot;stop / length&quot;]
Finish --&gt; ToolCalls[&quot;tool_calls&quot;]
Finish --&gt; More[&quot;继续累积&quot;]
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/stream-controller.js#L59-L168" target="_blank" rel="noreferrer">src/background/stream-controller.js#L59-L168</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/stream-controller.js#L59-L168" target="_blank" rel="noreferrer">src/background/stream-controller.js#L59-L168</a></li></ul><h3 id="事件类型识别" tabindex="-1">事件类型识别 <a class="header-anchor" href="#事件类型识别" aria-label="Permalink to &quot;事件类型识别&quot;">​</a></h3><p>流式事件分为以下几类：</p><table tabindex="0"><thead><tr><th>事件</th><th>含义</th><th>触发条件</th></tr></thead><tbody><tr><td><code>STREAM_START</code></td><td>开始流式输出</td><td>首次 flush 或 readSSEStream 启动时</td></tr><tr><td><code>STREAM_CHUNK</code></td><td>文本增量</td><td><code>delta.content</code> 存在且未达到节流阈值</td></tr><tr><td><code>STREAM_TOOL_CALL</code></td><td>工具调用通知</td><td><code>finish_reason === &#39;tool_calls&#39;</code></td></tr><tr><td><code>STREAM_DONE</code></td><td>流结束</td><td><code>[DONE]</code>、流结束或空闲超时后</td></tr><tr><td><code>AGENT_STREAM</code> / <code>AGENT_STREAM_DONE</code></td><td>Agent 命令输出</td><td>非模型 SSE，而是命令执行流</td></tr></tbody></table><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/stream-controller.js#L171-L252" target="_blank" rel="noreferrer">src/background/stream-controller.js#L171-L252</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/stream-controller.js#L411-L445" target="_blank" rel="noreferrer">src/background/stream-controller.js#L411-L445</a></li></ul><h3 id="数据完整性校验" tabindex="-1">数据完整性校验 <a class="header-anchor" href="#数据完整性校验" aria-label="Permalink to &quot;数据完整性校验&quot;">​</a></h3><p>当前实现的完整性校验相对轻量：</p><ul><li>对无效 JSON 行直接忽略。</li><li>对缺少 <code>choices[0]</code> 的 chunk 忽略。</li><li>对 <code>tool_calls</code> 使用 <code>normalizeToolCalls</code> 过滤空洞和无效元素，并补齐缺失的 <code>id</code>。</li><li>对 arguments 字段做防御性处理，兼容字符串和已解析对象。</li><li>对 <code>[DONE]</code> 和 <code>finish_reason</code> 分别处理，避免丢失最后一个 chunk 的数据。</li></ul><p>不足点：</p><ul><li>没有对 SSE 行的完整性做强校验，例如 <code>data:</code> 后必须是合法 JSON。</li><li>没有对 <code>choices</code> 的结构做深度校验。</li><li>没有对 <code>tool_calls.index</code> 的连续性做严格校验，只是容忍稀疏数组。</li><li>没有对 <code>usage</code> 的字段做 schema 校验。</li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/stream-controller.js#L19-L27" target="_blank" rel="noreferrer">src/background/stream-controller.js#L19-L27</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/stream-controller.js#L76-L130" target="_blank" rel="noreferrer">src/background/stream-controller.js#L76-L130</a></li></ul><h2 id="错误恢复机制" tabindex="-1">错误恢复机制 <a class="header-anchor" href="#错误恢复机制" aria-label="Permalink to &quot;错误恢复机制&quot;">​</a></h2><h3 id="网络中断检测" tabindex="-1">网络中断检测 <a class="header-anchor" href="#网络中断检测" aria-label="Permalink to &quot;网络中断检测&quot;">​</a></h3><p>网络中断可能表现为：</p><ul><li><code>reader.read()</code> 抛出异常。</li><li><code>fetch</code> 返回非 OK 状态。</li><li>长时间无数据触发空闲超时。</li></ul><p>当前处理策略：</p><ul><li><code>AbortError</code>：视为用户取消，不发送 <code>STREAM_DONE</code>，直接抛出异常。</li><li><code>StreamIdleTimeout</code>：主动 cancel reader，调用 <code>controller.finish()</code>，抛出带 <code>idleMs</code> 的错误。</li><li>其他错误：记录日志，调用 <code>controller.finish()</code>，抛出异常。</li><li>ReAct 层区分用户取消、空闲超时和普通错误，并写入执行日志。</li></ul><pre class="mermaid">flowchart TD
Error[&quot;流读取错误&quot;] --&gt; Name{&quot;错误类型？&quot;}
Name --&gt; |AbortError| Cancel[&quot;不发送 STREAM_DONE&quot;]
Cancel --&gt; ThrowAborted[&quot;抛出 AbortError&quot;]
Name --&gt; |StreamIdleTimeout| CancelReader[&quot;reader.cancel()&quot;]
CancelReader --&gt; Finish[&quot;controller.finish()&quot;]
Finish --&gt; ThrowTimeout[&quot;抛出 StreamIdleTimeout&quot;]
Name --&gt; |其他| FinishOther[&quot;controller.finish()&quot;]
FinishOther --&gt; ThrowOther[&quot;抛出普通错误&quot;]
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/stream-controller.js#L391-L409" target="_blank" rel="noreferrer">src/background/stream-controller.js#L391-L409</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/react-loop.js#L1514-L1585" target="_blank" rel="noreferrer">src/background/react-loop.js#L1514-L1585</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/stream-controller.js#L391-L409" target="_blank" rel="noreferrer">src/background/stream-controller.js#L391-L409</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/react-loop.js#L1514-L1585" target="_blank" rel="noreferrer">src/background/react-loop.js#L1514-L1585</a></li></ul><h3 id="断点续传" tabindex="-1">断点续传 <a class="header-anchor" href="#断点续传" aria-label="Permalink to &quot;断点续传&quot;">​</a></h3><p>当前代码中<strong>没有实现模型 SSE 的断点续传</strong>。原因包括：</p><ul><li>模型 SSE 通常是单向流，客户端无法像下载文件一样通过 Range 头续传。</li><li>流式响应包含对话上下文，不能简单从某个字节偏移恢复。</li><li>工具调用可能已经执行，盲目续传可能导致副作用重复。</li></ul><p>项目提供的“恢复”能力更接近“会话级恢复”和“上下文自愈”：</p><ul><li>上下文超限自愈：400 错误时裁剪消息并重试。</li><li>自动续跑：通过后台闹钟和通知机制提醒用户或自动恢复任务。</li><li>流式元素重连：侧面板在 DOM 脱落后补回缺失内容，但这不是网络断点续传。</li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/react-loop.js#L1520-L1548" target="_blank" rel="noreferrer">src/background/react-loop.js#L1520-L1548</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/chat-streaming.js#L728-L780" target="_blank" rel="noreferrer">src/side_panel/chat-streaming.js#L728-L780</a></li></ul><h3 id="状态重建" tabindex="-1">状态重建 <a class="header-anchor" href="#状态重建" aria-label="Permalink to &quot;状态重建&quot;">​</a></h3><p>状态重建主要体现在侧面板的流式元素重连逻辑中：</p><ul><li>如果流式元素脱离 DOM，<code>reconnectStreamingElement</code> 会将其重新插入。</li><li>补充 <code>_streamedContentMap</code> 中缓存的累积内容。</li><li>修复残留的思考指示器，插入“思考结果”徽章。</li><li>滚动到底部。</li></ul><p>这适用于 Service Worker 或页面生命周期导致的 DOM 暂时不可见场景，但不等同于网络层断点续传。</p><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/chat-streaming.js#L728-L780" target="_blank" rel="noreferrer">src/side_panel/chat-streaming.js#L728-L780</a></li></ul><h2 id="暂停、恢复与状态同步" tabindex="-1">暂停、恢复与状态同步 <a class="header-anchor" href="#暂停、恢复与状态同步" aria-label="Permalink to &quot;暂停、恢复与状态同步&quot;">​</a></h2><h3 id="用户交互控制" tabindex="-1">用户交互控制 <a class="header-anchor" href="#用户交互控制" aria-label="Permalink to &quot;用户交互控制&quot;">​</a></h3><p>用户可以通过以下方式控制流式响应：</p><ul><li>点击流式消息中的“停止生成”按钮，触发取消。</li><li>点击工具卡片中的“终止等待”，跳过当前工具等待。</li><li>命令执行工具支持“终止命令”，弹出确认对话框。</li><li>滚动到底部按钮支持拖拽定位，并在新内容到达时提示。</li></ul><p>取消路径：</p><ol><li>用户点击停止按钮。</li><li>ReAct 层通过 <code>abortSignal</code> 中断请求。</li><li><code>readSSEStream</code> 捕获 <code>AbortError</code>。</li><li>不发送 <code>STREAM_DONE</code>，避免残留状态。</li><li>ReAct 层记录“用户取消”错误并更新执行日志。</li></ol><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/chat-streaming.js#L717-L726" target="_blank" rel="noreferrer">src/side_panel/chat-streaming.js#L717-L726</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/chat-streaming.js#L1075-L1097" target="_blank" rel="noreferrer">src/side_panel/chat-streaming.js#L1075-L1097</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/stream-controller.js#L391-L397" target="_blank" rel="noreferrer">src/background/stream-controller.js#L391-L397</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/react-loop.js#L1551-L1585" target="_blank" rel="noreferrer">src/background/react-loop.js#L1551-L1585</a></li></ul><h3 id="后台处理" tabindex="-1">后台处理 <a class="header-anchor" href="#后台处理" aria-label="Permalink to &quot;后台处理&quot;">​</a></h3><p>后台处理包括：</p><ul><li>ReAct 循环包装 SW 保活心跳，防止 Service Worker 在长任务中被系统回收。</li><li>Agent 心跳每 60 秒刷新代理端认证时间。</li><li>流式节流通过 <code>streamChunkDelay</code> 控制。</li><li>空闲超时保护流式数据卡住。</li></ul><p>Service Worker 保活心跳由测试用例验证，确保任务执行期间定期调用轻量扩展 API，重置闲置计时器。</p><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/react-loop.js#L728-L746" target="_blank" rel="noreferrer">src/background/react-loop.js#L728-L746</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/index.js#L2250-L2306" target="_blank" rel="noreferrer">src/background/index.js#L2250-L2306</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/test/unit/sw-heartbeat.unit.test.js#L1-L18" target="_blank" rel="noreferrer">test/unit/sw-heartbeat.unit.test.js#L1-L18</a></li></ul><h3 id="状态同步" tabindex="-1">状态同步 <a class="header-anchor" href="#状态同步" aria-label="Permalink to &quot;状态同步&quot;">​</a></h3><p>状态同步通过以下机制保证：</p><ul><li><code>sessionId</code> 隔离流式元素和累积内容。</li><li><code>createStreamingElementAccessor</code> 提供按会话访问流式元素的函数。</li><li><code>deleteStreamingState</code> 清理指定会话的流式状态。</li><li><code>getStreamedContent</code> / <code>setStreamedContent</code> 读写累积内容。</li><li>工具卡片通过 <code>data-tool-call-id</code> 关联执行结果。</li><li>思考过程支持筛选成功/失败节点。</li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/chat-streaming.js#L584-L665" target="_blank" rel="noreferrer">src/side_panel/chat-streaming.js#L584-L665</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/chat-streaming.js#L603-L625" target="_blank" rel="noreferrer">src/side_panel/chat-streaming.js#L603-L625</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/chat-streaming.js#L953-L1116" target="_blank" rel="noreferrer">src/side_panel/chat-streaming.js#L953-L1116</a></li></ul><h2 id="性能优化" tabindex="-1">性能优化 <a class="header-anchor" href="#性能优化" aria-label="Permalink to &quot;性能优化&quot;">​</a></h2><h3 id="虚拟滚动" tabindex="-1">虚拟滚动 <a class="header-anchor" href="#虚拟滚动" aria-label="Permalink to &quot;虚拟滚动&quot;">​</a></h3><p>当前代码中没有实现完整的虚拟滚动。主要优化集中在：</p><ul><li>智能滚动：只在用户位于底部时自动跟随，避免频繁滚动干扰阅读。</li><li>防抖滚动：程序滚动时忽略 scroll 事件，防止误判为用户滚动。</li><li>补帧滚动：使用 <code>requestAnimationFrame</code> 确保布局稳定后再滚动。</li></ul><p>如果要引入虚拟滚动，应重点优化长消息列表，而不是单个流式消息内部的 Markdown 渲染。</p><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/chat-streaming.js#L159-L276" target="_blank" rel="noreferrer">src/side_panel/chat-streaming.js#L159-L276</a></li></ul><h3 id="增量-dom-更新" tabindex="-1">增量 DOM 更新 <a class="header-anchor" href="#增量-dom-更新" aria-label="Permalink to &quot;增量 DOM 更新&quot;">​</a></h3><p>流式渲染采用“累积全文 + 局部替换”的策略：</p><ul><li>每次 <code>STREAM_CHUNK</code> 都传入完整 <code>fullContent</code>。</li><li><code>updateStreamingMessage</code> 查找当前轮的 <code>thinking-content</code> 并替换其 innerHTML。</li><li>多轮 ReAct 会追加新的 <code>thinking-content</code>，而不是无限增长单个节点。</li><li>工具卡片按需创建，支持展开/折叠减少初始渲染压力。</li></ul><p>这种方式比纯追加 delta 更容易处理 Markdown 结构变化，但代价是每次都要重新渲染整段内容。对于超长回答，可考虑分块渲染或懒加载代码块。</p><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/chat-streaming.js#L787-L874" target="_blank" rel="noreferrer">src/side_panel/chat-streaming.js#L787-L874</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/chat-streaming.js#L935-L1116" target="_blank" rel="noreferrer">src/side_panel/chat-streaming.js#L935-L1116</a></li></ul><h3 id="内存管理" tabindex="-1">内存管理 <a class="header-anchor" href="#内存管理" aria-label="Permalink to &quot;内存管理&quot;">​</a></h3><p>关键内存管理点：</p><ul><li><code>fullContent</code> 和 <code>reasoningContent</code> 会持续增长，直到会话结束。</li><li><code>_streamedContentMap</code> 缓存累积内容，用于 DOM 重连。</li><li><code>_streamingElements</code> 缓存流式 DOM 元素。</li><li><code>agentNameCache</code> 缓存 Agent 名称，避免重复查询。</li><li>流式节流减少频繁 DOM 操作。</li><li>工具卡片默认折叠，减少初始渲染体积。</li></ul><p>建议：</p><ul><li>会话结束时清理 <code>_streamingElements</code> 和 <code>_streamedContentMap</code>。</li><li>对超长消息考虑截断或分页展示。</li><li>对工具参数大对象避免重复序列化。</li><li>谨慎使用 innerHTML，注意 XSS 防护。</li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/chat-streaming.js#L584-L665" target="_blank" rel="noreferrer">src/side_panel/chat-streaming.js#L584-L665</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/chat-streaming.js#L548-L566" target="_blank" rel="noreferrer">src/side_panel/chat-streaming.js#L548-L566</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/stream-controller.js#L36-L53" target="_blank" rel="noreferrer">src/background/stream-controller.js#L36-L53</a></li></ul><h2 id="调试与监控" tabindex="-1">调试与监控 <a class="header-anchor" href="#调试与监控" aria-label="Permalink to &quot;调试与监控&quot;">​</a></h2><h3 id="连接状态跟踪" tabindex="-1">连接状态跟踪 <a class="header-anchor" href="#连接状态跟踪" aria-label="Permalink to &quot;连接状态跟踪&quot;">​</a></h3><p>可通过以下方式跟踪流式连接状态：</p><ul><li>观察 <code>STREAM_START</code> 是否发送。</li><li>观察 <code>STREAM_CHUNK</code> 频率和内容。</li><li>观察 <code>STREAM_TOOL_CALL</code> 是否在工具调用时触发。</li><li>观察 <code>STREAM_DONE</code> 是否正常结束。</li><li>检查 <code>AbortError</code> 和 <code>StreamIdleTimeout</code> 是否出现。</li><li>检查执行日志中的 API 调用状态、耗时、finish_reason 和 token 用量。</li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/stream-controller.js#L171-L252" target="_blank" rel="noreferrer">src/background/stream-controller.js#L171-L252</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/react-loop.js#L1588-L1641" target="_blank" rel="noreferrer">src/background/react-loop.js#L1588-L1641</a></li></ul><h3 id="延迟分析" tabindex="-1">延迟分析 <a class="header-anchor" href="#延迟分析" aria-label="Permalink to &quot;延迟分析&quot;">​</a></h3><p>延迟来源包括：</p><ul><li>模型首包延迟。</li><li>模型增量间隔。</li><li>后台解析与节流延迟。</li><li>扩展消息传递延迟。</li><li>侧面板 Markdown 渲染延迟。</li><li>DOM 更新和滚动延迟。</li></ul><p>优化建议：</p><ul><li>调整 <code>streamChunkDelay</code>，平衡流畅度和渲染压力。</li><li>对极快工具设置最小显示延迟，避免状态闪烁。</li><li>使用 <code>requestAnimationFrame</code> 避免阻塞主线程。</li><li>对长 Markdown 内容考虑懒加载。</li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/stream-controller.js#L184-L217" target="_blank" rel="noreferrer">src/background/stream-controller.js#L184-L217</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/chat-streaming.js#L1154-L1161" target="_blank" rel="noreferrer">src/side_panel/chat-streaming.js#L1154-L1161</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/chat-streaming.js#L866-L874" target="_blank" rel="noreferrer">src/side_panel/chat-streaming.js#L866-L874</a></li></ul><h3 id="错误诊断" tabindex="-1">错误诊断 <a class="header-anchor" href="#错误诊断" aria-label="Permalink to &quot;错误诊断&quot;">​</a></h3><p>常见错误及定位方式：</p><table tabindex="0"><thead><tr><th>现象</th><th>可能原因</th><th>定位方式</th></tr></thead><tbody><tr><td>一直显示“思考中”</td><td>模型未返回内容或网络卡住</td><td>检查 <code>STREAM_CHUNK</code> 和空闲超时</td></tr><tr><td>工具卡片未显示</td><td><code>finish_reason</code> 不是 <code>tool_calls</code> 或 tool_calls 为空</td><td>检查 <code>STREAM_TOOL_CALL</code> 和 toolCalls 规范化</td></tr><tr><td>流式内容丢失</td><td>DOM 脱落且未重连</td><td>检查 <code>reconnectStreamingElement</code></td></tr><tr><td>停止生成后仍有 DONE</td><td>旧版本或消息泄漏</td><td>检查 <code>AbortError</code> 是否阻止 <code>STREAM_DONE</code></td></tr><tr><td>工具参数解析失败</td><td>arguments 格式异常</td><td>检查 JSON 解析和防御逻辑</td></tr></tbody></table><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/stream-controller.js#L76-L130" target="_blank" rel="noreferrer">src/background/stream-controller.js#L76-L130</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/chat-streaming.js#L728-L780" target="_blank" rel="noreferrer">src/side_panel/chat-streaming.js#L728-L780</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/chat-streaming.js#L953-L963" target="_blank" rel="noreferrer">src/side_panel/chat-streaming.js#L953-L963</a></li></ul><h2 id="使用示例与最佳实践" tabindex="-1">使用示例与最佳实践 <a class="header-anchor" href="#使用示例与最佳实践" aria-label="Permalink to &quot;使用示例与最佳实践&quot;">​</a></h2><h3 id="建立-sse-连接" tabindex="-1">建立 SSE 连接 <a class="header-anchor" href="#建立-sse-连接" aria-label="Permalink to &quot;建立 SSE 连接&quot;">​</a></h3><p>在本项目中，不建议直接复用 <code>readSSEStream</code> 作为通用 SSE 客户端，因为它与 <code>StreamController</code> 和扩展消息协议耦合较深。推荐做法：</p><ol><li>使用 <code>fetch</code> 发起模型 API 请求。</li><li>判断响应是否支持流式。</li><li>若支持，使用 <code>response.body.getReader()</code> 读取流。</li><li>使用自定义解析器或复用 <code>StreamController</code>。</li><li>通过 <code>chrome.runtime.sendMessage</code> 向侧面板推送事件。</li><li>处理 <code>AbortError</code>、空闲超时和网络错误。</li></ol><p>参考路径：</p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/react-loop.js#L1460-L1488" target="_blank" rel="noreferrer">src/background/react-loop.js#L1460-L1488</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/stream-controller.js#L287-L409" target="_blank" rel="noreferrer">src/background/stream-controller.js#L287-L409</a></li></ul><h3 id="处理增量数据" tabindex="-1">处理增量数据 <a class="header-anchor" href="#处理增量数据" aria-label="Permalink to &quot;处理增量数据&quot;">​</a></h3><p>最佳实践：</p><ul><li>不要假设每个 chunk 都有 <code>choices[0].delta.content</code>。</li><li>优先提取 <code>usage</code>，即使后续 choices 为空。</li><li>累积 <code>tool_calls</code> 时容忍 index 跳号。</li><li>在 <code>finish_reason</code> 之前处理 delta，避免丢失最后一个 chunk。</li><li>使用节流机制避免频繁 DOM 更新。</li><li>在侧面板使用累积全文渲染，而不是纯追加 delta。</li></ul><p>参考路径：</p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/stream-controller.js#L83-L168" target="_blank" rel="noreferrer">src/background/stream-controller.js#L83-L168</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/chat-streaming.js#L787-L874" target="_blank" rel="noreferrer">src/side_panel/chat-streaming.js#L787-L874</a></li></ul><h3 id="实现断点续传" tabindex="-1">实现断点续传 <a class="header-anchor" href="#实现断点续传" aria-label="Permalink to &quot;实现断点续传&quot;">​</a></h3><p>由于模型 SSE 不支持传统断点续传，建议采用“会话级恢复”方案：</p><ol><li>在任务开始前保存 checkpoint。</li><li>任务中断后保留会话上下文。</li><li>恢复时重新发起 API 请求，而不是续传旧流。</li><li>对已执行的工具调用做幂等处理或跳过。</li><li>对用户可见的状态做重建，例如消息列表、工具卡片、执行日志。</li></ol><p>参考路径：</p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/react-loop.js#L1520-L1548" target="_blank" rel="noreferrer">src/background/react-loop.js#L1520-L1548</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/chat-streaming.js#L728-L780" target="_blank" rel="noreferrer">src/side_panel/chat-streaming.js#L728-L780</a></li></ul><h3 id="配置流式行为" tabindex="-1">配置流式行为 <a class="header-anchor" href="#配置流式行为" aria-label="Permalink to &quot;配置流式行为&quot;">​</a></h3><p>流式行为可通过配置控制：</p><table tabindex="0"><thead><tr><th>配置项</th><th>作用</th><th>默认行为</th></tr></thead><tbody><tr><td><code>streamEnabled</code></td><td>是否启用流式模式</td><td>默认启用，除非显式设为 false</td></tr><tr><td><code>streamChunkDelay</code></td><td>流式 chunk 节流延迟</td><td>默认 0，表示尽可能快</td></tr><tr><td><code>streamExpandTools</code></td><td>工具卡片是否默认展开</td><td>由侧面板状态控制</td></tr></tbody></table><p>参考路径：</p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/config/constants.js#L29" target="_blank" rel="noreferrer">src/config/constants.js#L29</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/stream-controller.js#L37-L41" target="_blank" rel="noreferrer">src/background/stream-controller.js#L37-L41</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/chat-streaming.js#L1030-L1031" target="_blank" rel="noreferrer">src/side_panel/chat-streaming.js#L1030-L1031</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/react-loop.js#L1460-L1488" target="_blank" rel="noreferrer">src/background/react-loop.js#L1460-L1488</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/stream-controller.js#L37-L41" target="_blank" rel="noreferrer">src/background/stream-controller.js#L37-L41</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/config/constants.js#L29" target="_blank" rel="noreferrer">src/config/constants.js#L29</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/chat-streaming.js#L1030-L1031" target="_blank" rel="noreferrer">src/side_panel/chat-streaming.js#L1030-L1031</a></li></ul><h2 id="故障排查清单" tabindex="-1">故障排查清单 <a class="header-anchor" href="#故障排查清单" aria-label="Permalink to &quot;故障排查清单&quot;">​</a></h2><table tabindex="0"><thead><tr><th>问题</th><th>检查项</th><th>处理方式</th></tr></thead><tbody><tr><td>流式无输出</td><td>是否发送 <code>STREAM_START</code></td><td>检查 StreamController 初始化</td></tr><tr><td>流式卡顿</td><td>是否触发空闲超时</td><td>检查网络、模型响应、<code>STREAM_IDLE_TIMEOUT_MS</code></td></tr><tr><td>工具卡片不显示</td><td>是否发送 <code>STREAM_TOOL_CALL</code></td><td>检查 <code>finish_reason</code> 和 tool_calls</td></tr><tr><td>停止生成无效</td><td>是否抛出 <code>AbortError</code></td><td>检查 abortSignal 和取消逻辑</td></tr><tr><td>流式内容丢失</td><td>是否 DOM 脱落</td><td>检查 <code>reconnectStreamingElement</code></td></tr><tr><td>工具参数解析失败</td><td>arguments 是否合法 JSON</td><td>检查解析和防御逻辑</td></tr><tr><td>滚动异常</td><td>是否误判用户滚动</td><td>检查 <code>_userScrolledUp</code> 和 <code>_isProgramScroll</code></td></tr><tr><td>Service Worker 被回收</td><td>是否开启 SW 保活心跳</td><td>检查 <code>startSwHeartbeat</code></td></tr></tbody></table><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/stream-controller.js#L287-L409" target="_blank" rel="noreferrer">src/background/stream-controller.js#L287-L409</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/chat-streaming.js#L728-L780" target="_blank" rel="noreferrer">src/side_panel/chat-streaming.js#L728-L780</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/chat-streaming.js#L159-L276" target="_blank" rel="noreferrer">src/side_panel/chat-streaming.js#L159-L276</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/react-loop.js#L728-L746" target="_blank" rel="noreferrer">src/background/react-loop.js#L728-L746</a></li></ul><h2 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to &quot;结论&quot;">​</a></h2><p>本项目的流式响应处理器以 <code>StreamController</code> 为核心，结合 <code>readSSEStream</code> 的流式读取、空闲超时保护和工具调用检测，实现了从模型 SSE 到侧面板渲染的完整链路。其优势在于：</p><ul><li>支持 OpenAI 兼容格式的 SSE 流。</li><li>支持文本增量、推理内容、工具调用和 Token 用量。</li><li>支持节流渲染、工具卡片实时展示和多轮 ReAct。</li><li>支持用户取消、空闲超时和优雅关闭。</li><li>支持侧面板流式元素重连和状态同步。</li></ul><p>需要注意的限制包括：</p><ul><li>模型 SSE 没有内置自动重连。</li><li>没有传统意义上的断点续传。</li><li>流式渲染使用累积全文替换，可能对超长消息造成性能压力。</li><li>心跳机制区分模型 SSE 和 Agent 保活，不应混淆。</li></ul><p>未来优化方向可包括：</p><ul><li>增加更严格的 SSE 数据校验。</li><li>引入虚拟滚动优化长消息列表。</li><li>对超长 Markdown 内容做分块或懒加载。</li><li>增加流式连接监控指标，如首包延迟、增量间隔、错误率。</li><li>在业务层实现更完善的会话恢复和工具调用幂等控制。</li></ul>`,236)])])}const u=r(l,[["render",i]]);export{b as __pageData,u as default};
